# ==============================================================================# IOTEC MISSION CONTROL# 005_LOG_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)cur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS system_logs(    id INTEGER PRIMARY KEY AUTOINCREMENT,    timestamp TEXT,    level TEXT,    module TEXT,    message TEXT)""")conn.commit()def log(level, module, message):    cur.execute(        """        INSERT INTO system_logs(            timestamp,            level,            module,            message        )        VALUES(?,?,?,?)        """,        (            datetime.now().isoformat(),            level,            module,            message        )    )    conn.commit()    print(f"[{level}] {module} -> {message}")if __name__ == "__main__":    log("INFO", "005_LOG_ENGINE", "Mission Control iniciado")    log("INFO", "KERNEL", "Kernel Online")    log("INFO", "DATABASE", "SQLite conectado")    log("INFO", "EVENT_BUS", "Fila criada")    cur.execute("SELECT COUNT(*) FROM system_logs")    total = cur.fetchone()[0]    print()    print("=" * 80)    print(f"TOTAL LOGS: {total}")    print("=" * 80)    conn.close()

